stamp=datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S');marker='qa_bundle_'+stamp;uid=marker+'_s1001';stage=json.loads((ROOT/'stage.json').read_text())['stage'];result={'marker':marker,'sqlTemporaryOnly':True}
