 code="""const{MongoClient}=require('/linhhoasu/lhs/newServer/node_modules/mongodb');(async()=>{const c=new MongoClient('mongodb://127.0.0.1:27017');await c.connect();const db=c.db('lhs_s1001'),p=await db.collection('players').findOne({isBot:true});delete p._id;delete p.__v;Object.assign(p,{userId:__UID__,playerId:__MARKER__,name:__MARKER__,accountId:'',isBot:false,serverId:1001,items:{},currencies:{diamond:0,gold:0,silver:0},mailClaimLedger:[],fashionInfo:{fashions:{},activateFashion:[],fashionData:[],dress:[]}});delete p.botWorker;delete p.inviteCode;await db.collection('players').insertOne(p);await c.close();console.log(JSON.stringify({created:true}));})().catch(e=>{console.error(e.name);process.exitCode=1;});""".replace('__UID__',json.dumps(uid)).replace('__MARKER__',json.dumps(marker))
