 result['delivery']=json.loads(run(s,'php',script));events=result['delivery']['events']
 code=r"""const assert=require('assert/strict'),{MongoClient}=require('/linhhoasu/lhs/newServer/node_modules/mongodb'),WebSocket=require('/linhhoasu/lhs/newServer/node_modules/ws'),{Pack,Unpack}=require('/linhhoasu/lhs/newServer/src/protocol/Codec');const uid=__UID__,base=__MARKER__,events=__EVENTS__;let ws;const wait=ms=>new Promise(r=>setTimeout(r,ms));(async()=>{const c=new MongoClient('mongodb://127.0.0.1:27017');await c.connect();const db=c.db('lhs_s1001'),mails=await db.collection('mails').find({userId:uid,eventKey:{$in:events}}).toArray();assert.equal(mails.length,2);assert.deepEqual(mails.map(m=>m.attachments.length).sort((a,b)=>a-b),[4,10]);ws=new WebSocket('ws://127.0.0.1:9200',{headers:{Origin:'http://127.0.0.1'}});let seq=8900;function recv(tag,id){return new Promise((r,j)=>{const timer=setTimeout(()=>{ws.off('q',on);j(new Error('WS_TIMEOUT'))},12000);function on(p){if(p.tag===tag&&p.msgUid===id){clearTimeout(timer);ws.off('q',on);r(p);}}ws.on('q',on);});}ws.on('message',raw=>{const b=Buffer.from(raw);const values=Unpack(b.buffer.slice(b.byteOffset,b.byteOffset+b.byteLength));for(const p of Array.isArray(values)?values:[values])ws.emit('q',p);});await new Promise((r,j)=>{ws.once('open',r);ws.once('error',j)});async function rpc(tag,data){const id=++seq,p=recv(tag,id);ws.send(Pack(tag,data,id));return p;}assert.equal((await rpc(1,{platformuid:base,userid:base,userId:base,serverid:1001,serverId:1001,firstName:'QA bundle'})).data.result,0);const got=await rpc(1103,{ids:mails.map(m=>String(m._id))});assert.equal(got.data.result,0);let p=await db.collection('players').findOne({userId:uid});for(const id of [28041,28042,28043,28049])assert((p.fashionInfo.activateFashion||[]).includes(id));for(const id of [19,24,50,55,60,65])assert(Number(p.items[id])>=1);const duplicate=await rpc(1103,{ids:mails.map(m=>String(m._id))});assert.equal(duplicate.data.rewardInfo.items.length,0);ws.close();await wait(1500);p=await db.collection('players').findOne({userId:uid});assert((p.fashionInfo.activateFashion||[]).includes(28043));await c.close();console.log(JSON.stringify({result:'PASS',mails:2,attachmentCounts:[4,10],nativeOwnership:true,retryNoRegrant:true,persistAfterClose:true,upstreamPayment:false}));})().catch(e=>{if(ws)ws.terminate();console.error(e.stack);process.exitCode=1;});""".replace('__UID__',json.dumps(uid)).replace('__MARKER__',json.dumps(marker)).replace('__EVENTS__',json.dumps(events))
 result['claim']=node(code)
